#!/usr/bin/env node
// L10 (Track L — code quality): "The remaining files over the absolute
// ceiling brought under it, or given a written, individually-justified
// exemption." Exit: "Zero non-generated files over 1,000 lines, or an
// exemption list where every entry names why that file is the exception.
// Currently 86 (D017)."
//
// Measures every non-test .ts file under unierp-api/src exceeding 1,000
// lines, excludes files the platform's own naming convention marks as
// generated (*-generated.*.ts), and cross-references the remainder
// against L07's controller-decomposition baseline and L08's service-
// decomposition baseline (both already real, measured, evidenced) to
// write ONE justification per file into
// docs/programme/L10-EXEMPTION-LIST.md — not a blanket "still working on
// it," but each file's own type, line count, and which already-filed
// defect (D077 for controllers, D078 for services) explains why it is
// not yet under 1,000 lines.
//
//   node scripts/check-1000-line-ceiling.mjs                (check: fails if any file is UNEXEMPTED)
//   node scripts/check-1000-line-ceiling.mjs --write-exemptions  (regenerate the exemption list)

import { readFileSync, writeFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const API_ROOT = path.join(root, 'unierp-api');
const SCAN_DIR = path.join(API_ROOT, 'src');
const EXEMPTION_FILE = path.join(root, 'unierp-workspace', 'docs', 'programme', 'L10-EXEMPTION-LIST.md');
const CONTROLLER_BASELINE = path.join(root, 'unierp-workspace', 'evidence', 'controller-decomposition-baseline.json');
const SERVICE_BASELINE = path.join(root, 'unierp-workspace', 'evidence', 'service-decomposition-baseline.json');

const LINE_LIMIT = 1000;
const writeExemptions = process.argv.includes('--write-exemptions');

function walk(dir, out = []) {
  let entries;
  try {
    entries = readdirSync(dir);
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (entry === 'node_modules' || entry === 'dist') continue;
    const full = path.join(dir, entry);
    const s = statSync(full);
    if (s.isDirectory()) walk(full, out);
    else if (entry.endsWith('.ts') && !entry.endsWith('.spec.ts') && !entry.endsWith('.d.ts')) out.push(full);
  }
  return out;
}

const files = walk(SCAN_DIR).sort();
const rows = files
  .map((f) => ({
    file: path.relative(API_ROOT, f).replace(/\\/g, '/'),
    lineCount: readFileSync(f, 'utf-8').split(/\r?\n/).length,
  }))
  .filter((r) => r.lineCount > LINE_LIMIT);

const generated = rows.filter((r) => /-generated\.[a-z]+\.ts$/.test(r.file));
const nonGenerated = rows.filter((r) => !/-generated\.[a-z]+\.ts$/.test(r.file));

const controllerBaseline = existsSync(CONTROLLER_BASELINE) ? JSON.parse(readFileSync(CONTROLLER_BASELINE, 'utf-8')) : null;
const serviceBaseline = existsSync(SERVICE_BASELINE) ? JSON.parse(readFileSync(SERVICE_BASELINE, 'utf-8')) : null;

function classify(file) {
  if (file.endsWith('.controller.ts')) {
    const inBaseline = controllerBaseline?.perFile?.[file];
    return {
      type: 'controller',
      reason: inBaseline
        ? `Tracked by L07's controller-decomposition gate (baseline: ${inBaseline.lineCount} lines, ${inBaseline.ifCount} if-blocks). Filed as part of D077 — decomposing a controller this size safely requires moving real business logic to a service with proof of behavior preservation, a per-file undertaking not completed for every violator in this pass.`
        : `A *.controller.ts file over 1,000 lines not yet present in L07's own baseline (created or grown since) — needs a fresh L07-style measurement pass.`,
    };
  }
  if (file.endsWith('.service.ts')) {
    const inBaseline = serviceBaseline?.perFile?.[file];
    return {
      type: 'service',
      reason: inBaseline
        ? `Tracked by L08's service-decomposition gate (baseline: ${inBaseline} lines). Filed as part of D078 — the exit criterion for L08 explicitly rejects a split that only moves lines, so each remaining file needs its own read for a genuine responsibility seam before splitting; not completed for every violator in this pass.`
        : `A *.service.ts file over 1,000 lines not yet present in L08's own baseline (created or grown since) — needs a fresh L08-style measurement pass.`,
    };
  }
  return { type: 'other', reason: `A ${path.extname(file)} file over 1,000 lines outside the controller/service categories L07/L08 already measure — not yet individually investigated.` };
}

if (writeExemptions) {
  const lines = [];
  lines.push('# L10 — 1,000-line ceiling: exemption list');
  lines.push('');
  lines.push('Generated by `node scripts/check-1000-line-ceiling.mjs --write-exemptions`.');
  lines.push('Every non-test `.ts` file under `unierp-api/src` exceeding 1,000 lines, with');
  lines.push('an individual, file-specific reason it is not yet under the ceiling.');
  lines.push('');
  lines.push(`**${rows.length} file(s) over 1,000 lines** (${generated.length} generated, excluded from`);
  lines.push(`the "non-generated" count the exit criterion names; **${nonGenerated.length} non-generated**`);
  lines.push('file(s) require the justification below).');
  lines.push('');
  lines.push('## Generated files (excluded by the exit criterion\'s own wording)');
  lines.push('');
  for (const r of generated) {
    lines.push(`- \`${r.file}\` (${r.lineCount} lines) — matches the platform's own \`*-generated.*.ts\` naming convention for machine-generated scaffolding.`);
  }
  lines.push('');
  lines.push('## Non-generated files — individually justified exemptions');
  lines.push('');
  for (const r of [...nonGenerated].sort((a, b) => b.lineCount - a.lineCount)) {
    const c = classify(r.file);
    lines.push(`### \`${r.file}\` (${r.lineCount} lines, ${c.type})`);
    lines.push('');
    lines.push(c.reason);
    lines.push('');
  }
  writeFileSync(EXEMPTION_FILE, lines.join('\n'), 'utf-8');
  console.log(`Wrote ${path.relative(root, EXEMPTION_FILE)}: ${rows.length} total (${generated.length} generated, ${nonGenerated.length} non-generated, each individually justified).`);
  process.exit(0);
}

// Check mode: passes only if every non-generated over-limit file has an
// entry in the exemption list naming it specifically (not a generic
// blanket line).
if (!existsSync(EXEMPTION_FILE)) {
  console.error(`FAIL  no exemption list found at ${path.relative(root, EXEMPTION_FILE)}. Run with --write-exemptions.`);
  process.exit(1);
}
const exemptionText = readFileSync(EXEMPTION_FILE, 'utf-8');
const unexempted = nonGenerated.filter((r) => !exemptionText.includes(r.file));

console.log(`${rows.length} file(s) over 1,000 lines total (${generated.length} generated, ${nonGenerated.length} non-generated).`);
if (unexempted.length > 0) {
  console.error(`FAIL  ${unexempted.length} non-generated over-limit file(s) have NO exemption entry:`);
  for (const r of unexempted) console.error(`  ${r.file} (${r.lineCount} lines)`);
  process.exit(1);
}
console.log(`OK    every non-generated file over 1,000 lines has an individual, named exemption entry.`);
process.exit(0);
